<template><div class="page fade-up"><div class="head-links"><router-link :to="`/projects/${id}/novel`" class="back">← 小说章节</router-link></div><div class="page-head"><div><h1>故事圣经</h1><p class="sub">汇总剧情单元，审核后供后续分集改编使用。</p></div><div class="actions"><span v-if="bible" class="badge">{{ bible.status }}</span><button class="btn btn-secondary" :disabled="busy" @click="generate">生成草稿</button><button class="btn" :disabled="busy || !bible || bible.status !== 'draft'" @click="approve">审核通过</button><router-link v-if="bible?.status === 'approved'" :to="`/projects/${id}/adaptation`" class="btn">分集规划 →</router-link></div></div><div v-if="error" class="card error">{{ error }}</div><div v-if="!bible" class="card empty">请先完成全部章节分析和剧情单元生成。</div><form v-else class="card form" @submit.prevent="save"><label>核心前提<textarea v-model="form.premise" class="textarea" rows="4"/></label><label v-for="f in fields" :key="f.key">{{ f.label }}<textarea v-model="form[f.key]" class="textarea" rows="7"/></label><button class="btn" :disabled="busy">保存为待审核草稿</button></form></div></template>
<script setup>
import { onMounted, reactive, ref } from 'vue'; import { useRoute } from 'vue-router'; import { api } from '../api';
const id=useRoute().params.id,bible=ref(null),busy=ref(false),error=ref(''); const form=reactive({}); const fields=[['world_rules','世界规则'],['main_plot','主线'],['subplots','支线'],['timeline_json','时间线'],['relationships_json','人物关系'],['clue_ledger_json','伏笔台账'],['location_bible_json','地点'],['prop_bible_json','道具']].map(([key,label])=>({key,label}));
function apply(v){bible.value=v;Object.assign(form,v)} async function load(){try{apply((await api.storyBible(id)).data)}catch(e){if(e.response?.status!==404)error.value=e.response?.data?.error||e.message}} async function generate(){busy.value=true;error.value='';try{apply((await api.generateStoryBible(id)).data.story_bible)}catch(e){error.value=e.response?.data?.error||e.message}finally{busy.value=false}} async function save(){busy.value=true;try{const data={premise:form.premise};for(const f of fields)data[f.key]=form[f.key]||'';apply((await api.updateStoryBible(id,data)).data)}catch(e){error.value=e.response?.data?.error||e.message}finally{busy.value=false}} async function approve(){busy.value=true;try{apply((await api.approveStoryBible(id)).data)}catch(e){error.value=e.response?.data?.error||e.message}finally{busy.value=false}} onMounted(load)
</script><style scoped>.page-head{display:flex;justify-content:space-between;gap:16px;margin-bottom:18px}.actions{display:flex;gap:10px;align-items:center}.form{padding:22px;display:grid;gap:18px}.form label{display:grid;gap:8px;font-weight:600}.empty,.error{padding:30px}.error{color:var(--red)}@media(max-width:700px){.page-head{display:block}.actions{margin-top:12px;flex-wrap:wrap}}</style>
